import battle_simulator
import random

monster_a = {
    "id": "m_cindermaw",
    "name": "Cindermaw",
    "element": "pyro",
    "moves": ['pyroclasm', 'ember', 'focus', 'gambit']
}

def evaluate(strat, trials=10000):
    monster_b = {
        "id": "m_random",
        "name": "Random Opponent",
        "element": "pyro",
        "moves": ["ember", "pyroclasm", "mend", "bulwark"]
    }
    strategy_b = {
        "opening_move": "pyroclasm",
        "move_weights": {"pyroclasm": 1.0, "ember": 0.5, "mend": 0.2, "bulwark": 0.2},
        "switch_to_defense_below": 0.25,
        "defense_move": "mend",
        "aggression": 0.6,
        "prefer_super_effective": True
    }

    wins = 0
    for i in range(trials):
        monster_b["element"] = random.choice(["pyro", "flora", "aqua", "gale", "volt", "terra"])
        winner = battle_simulator.simulate_battle(monster_a, strat, monster_b, strategy_b)
        if winner == "a":
            wins += 1
    return wins / trials

# Let's test different defense moves and thresholds with Gambit fallback
thresholds = [0.0, 0.1, 0.2, 0.25, 0.3, 0.35, 0.4]
def_moves = ["focus", "pyroclasm", "gambit", "ember"]

for t in thresholds:
    for m in def_moves:
        strat = {
            "opening_move": "pyroclasm",
            "move_weights": {
                "pyroclasm": 0.8,
                "ember": 0.2,
                "focus": 0.0,
                "gambit": 1.0
            },
            "switch_to_defense_below": t,
            "defense_move": m,
            "aggression": 1.0,
            "prefer_super_effective": True
        }
        wr = evaluate(strat, 2000)
        print(f"Threshold: {t}, Defense Move: {m} -> {wr:.2%}")
